from copy import deepcopy


def dispatch_primary(events, handlers, primary):
    if not isinstance(events, list) or not isinstance(handlers, dict) or not isinstance(primary, str):
        raise ValueError("invalid arguments")
    for event in events:
        if not isinstance(event, dict) or set(event) != {"channel", "payload"}:
            raise ValueError("invalid event")
        if not isinstance(event["channel"], str):
            raise ValueError("invalid event channel")
    for channel, callbacks in handlers.items():
        if not isinstance(channel, str) or not isinstance(callbacks, list):
            raise ValueError("invalid handler entry")
        if any(not callable(callback) for callback in callbacks):
            raise ValueError("invalid callback")

    callbacks = handlers.get(primary, [])
    result = []
    for event in events:
        if event["channel"] is primary:
            for callback in callbacks:
                result.append(callback(deepcopy(event["payload"])))
    return result
```

